begin;
set local search_path=public,extensions;
select plan(16);
update public.profiles set must_change_password=false;
insert into auth.sessions(id,user_id,created_at,updated_at) select id,id,now(),now() from public.profiles on conflict(id) do nothing;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000006","session_id":"10000000-0000-4000-8000-000000000006","role":"authenticated"}',true);
select throws_ok($$select public.learning_write('assignment.create',null,'{"courseId":"20000000-0000-4000-8000-000000000001","title":"Forbidden"}')$$,'42501',null,'student cannot author work');
select throws_ok($$select public.learning_write('attempt.start','40000000-0000-4000-8000-000000000001','{}')$$,'42501',null,'nonmember cannot attempt quiz');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000005","session_id":"10000000-0000-4000-8000-000000000005","role":"authenticated"}',true);
select lives_ok($$select public.learning_write('submission.put','30000000-0000-4000-8000-000000000001','{"textAnswer":"My answer"}')$$,'enrolled student can submit');
select lives_ok($$select public.learning_write('attempt.start','40000000-0000-4000-8000-000000000001','{}')$$,'enrolled student can start');
select throws_ok($$select public.learning_write('attempt.start','40000000-0000-4000-8000-000000000001','{}')$$,'P0001','Only one attempt is allowed','second attempt rejected');
select is((public.learning_write('attempt.submit','40000000-0000-4000-8000-000000000001','{"answers":{"50000000-0000-4000-8000-000000000001":["b"]}}')->>'score')::numeric,5::numeric,'server grades correct answers');
select throws_ok($$select public.learning_write('attempt.submit','40000000-0000-4000-8000-000000000001','{"answers":{}}')$$,'P0001','Attempt already submitted','second submission rejected');
select throws_ok($$select public.community_write('complaint.review','80000000-0000-4000-8000-000000000001','{"status":"in_review"}')$$,'42501',null,'complainant cannot change status');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000003","session_id":"10000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.learning_write('assignment.delete','30000000-0000-4000-8000-000000000001','{}')$$,'42501',null,'unrelated teacher cannot delete assignment');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","session_id":"10000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok(format('select public.learning_write(''submission.grade'',''%s'',''{"marks":21}'')',(select id from public.submissions where student_id='10000000-0000-4000-8000-000000000005')),'23514','Marks outside allowed range','grade above maximum rejected');
select lives_ok(format('select public.learning_write(''submission.grade'',''%s'',''{"marks":18,"feedback":"Good"}'')',(select id from public.submissions where student_id='10000000-0000-4000-8000-000000000005')),'assigned teacher can grade');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000005","session_id":"10000000-0000-4000-8000-000000000005","role":"authenticated"}',true);
select lives_ok($$select public.learning_write('submission.put','30000000-0000-4000-8000-000000000001','{"textAnswer":"Revised answer"}')$$,'student can resubmit before deadline');
select is((select marks_obtained from public.submissions where student_id=auth.uid()),null::numeric,'resubmission clears grade');
reset role;
update public.assignments set due_at=now()-interval '1 minute',allow_late=false where id='30000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.learning_write('submission.put','30000000-0000-4000-8000-000000000001','{"textAnswer":"Late"}')$$,'P0001','Deadline has passed','late work rejected on server clock');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.community_write('complaint.review','80000000-0000-4000-8000-000000000001','{"status":"resolved","adminResponse":"Fixed"}')$$,'P0001','Invalid complaint status transition','cannot skip review state');
select lives_ok($$select public.community_write('complaint.review','80000000-0000-4000-8000-000000000001','{"status":"in_review","adminResponse":"Investigating"}')$$,'admin can begin review');
select * from finish();
rollback;
